// Crop master sheets into standalone references. Coordinates remain editable for legacy layouts.
const cropDialog=document.createElement('dialog');cropDialog.style.width='960px';cropDialog.innerHTML='<div class="modal-head"><h2>裁剪单视图</h2><button id="cropClose">✕</button></div><p>选择一个视角，可调整像素范围。请确认结果只包含单个视角。旧版母图请手动调整范围。</p><label>视角<select id="cropAngle"></select></label><div class="field-row" id="cropFields"></div><canvas id="cropOverview" style="width:100%;max-height:270px;object-fit:contain"></canvas><p>裁剪结果</p><canvas id="cropPreview" style="max-width:100%;max-height:270px;object-fit:contain;background:white"></canvas><p id="cropStatus" role="status"></p><button id="cropSave" class="primary">保存单视图供分镜／视频使用</button>';document.body.append(cropDialog);
let cropContext=null,cropWorking=false;
for(const p of CharacterSheet.spec.panels){const o=document.createElement('option');o.value=p.angle;o.textContent=p.label;cropDialog.querySelector('#cropAngle').append(o)}
for(const [key,label] of [['x','左边 x'],['y','上边 y'],['width','宽度'],['height','高度']]){const l=document.createElement('label');l.textContent=label;const i=document.createElement('input');i.type='number';i.step='1';i.min=key==='x'||key==='y'?'0':'1';i.id='crop-'+key;i.oninput=updateCropPreview;l.append(i);cropDialog.querySelector('#cropFields').append(l)}
function updateCropPreview(){if(!cropContext)return;const button=cropDialog.querySelector('#cropSave');button.disabled=true;try{
  const {image}=cropContext,r=CharacterSheet.cropRect(Object.fromEntries(['x','y','width','height'].map(k=>[k,cropDialog.querySelector('#crop-'+k).value])),image.naturalWidth,image.naturalHeight);
  const overview=cropDialog.querySelector('#cropOverview');overview.width=image.naturalWidth;overview.height=image.naturalHeight;const oc=overview.getContext('2d');oc.drawImage(image,0,0);oc.strokeStyle='#11b981';oc.lineWidth=Math.max(2,overview.width/300);oc.strokeRect(r.x,r.y,r.width,r.height);
  const canvas=cropDialog.querySelector('#cropPreview');canvas.width=r.width;canvas.height=r.height;canvas.getContext('2d').drawImage(image,r.x,r.y,r.width,r.height,0,0,r.width,r.height);cropContext.rect=r;cropDialog.querySelector('#cropStatus').textContent=r.width+' × '+r.height+' · 请检查没有相邻视角';button.disabled=cropWorking;
}catch(e){cropContext.rect=null;cropDialog.querySelector('#cropStatus').textContent=e.message}}
function setCropPanel(){const r=CharacterSheet.panelRect(cropDialog.querySelector('#cropAngle').value,cropContext.image.naturalWidth,cropContext.image.naturalHeight);for(const k of ['x','y','width','height'])cropDialog.querySelector('#crop-'+k).value=r[k];updateCropPreview()}
cropDialog.querySelector('#cropAngle').onchange=setCropPanel;cropDialog.querySelector('#cropClose').onclick=()=>{if(!cropWorking)cropDialog.close()};
async function openSheetCrop(c,sheet){try{const image=await loadSheetImage(sheet.image_url);cropContext={character:c,sheet,image};setCropPanel();cropDialog.showModal()}catch(e){toast(e.message)}}
cropDialog.querySelector('#cropSave').onclick=async()=>{if(cropWorking||!cropContext?.rect)return;cropWorking=true;updateCropPreview();const context=cropContext,angle=cropDialog.querySelector('#cropAngle').value;try{
  const label=CharacterSheet.spec.panels.find(p=>p.angle===angle).label,blob=await new Promise(resolve=>cropDialog.querySelector('#cropPreview').toBlob(resolve,'image/png'));if(!blob)throw Error('无法生成裁剪图片');
  const params=new URLSearchParams({project_id:data.project_id||data.title,character_id:context.character.id||context.character.character_id||context.character.name,layout:'single_view',sources:JSON.stringify([{sheet_id:context.sheet.id,angle,crop:context.rect}])});
  const response=await fetch('/api/contact-sheet?'+params,{method:'POST',headers:{'Content-Type':'image/png'},body:blob});const result=await response.json();if(!response.ok)throw Error(result.error||'保存失败');
  context.character.singleViews??=[];context.character.singleViews.push({...result,angle,label,crop:context.rect,source_sheet_id:context.sheet.id});context.character.reference_images??={};context.character.reference_images[angle]=result.image_url;save();render();cropDialog.close();toast('单视图已保存，可在分镜参考图中选择');
}catch(e){cropDialog.querySelector('#cropStatus').textContent=e.message}finally{cropWorking=false;updateCropPreview()}};
cropDialog.addEventListener('cancel',e=>{if(cropWorking)e.preventDefault()});
const charactersBeforeCrop=characters;
characters=function(){charactersBeforeCrop();const c=data.characters[ci],card=document.querySelector('#contactSheetDisplay');if(!c||!card)return;const button=document.createElement('button');button.id='cropCharacterView';button.textContent='裁剪单视图';button.onclick=()=>openSheetCrop(c,c.contactSheets[c.contactSheetActive??c.contactSheets.length-1]);card.append(button);const help=document.createElement('p');help.className='subtle';help.textContent=CharacterSheet.spec.video_policy;card.append(help);for(const view of c.singleViews||[]){const link=document.createElement('a');link.href=view.image_url+'?download=1';link.download=c.name+'-'+view.label+'.png';link.textContent='下载 '+view.label;link.style.cssText='display:inline-block;margin:6px 12px 6px 0';card.append(link)}};
const charactersBeforeSheetTemplate=characters;
characters=function(){const c=data.characters[ci];if(c){c.generation??={};c.generation.character_sheet??=JSON.parse(JSON.stringify(CharacterSheet.spec));c.generation.character_sheet.generation_order=['portrait','front','left','back'];c.generation.character_sheet.identity_reference='portrait';c.generation.character_sheet.view_sizes=JSON.parse(JSON.stringify(CharacterSheet.spec.view_sizes));}charactersBeforeSheetTemplate();const head=document.querySelector('#panel .section-head');if(!head)return;const link=document.createElement('a');link.href='/character-template.json';link.target='_blank';link.download='characters-template.json';link.textContent='下载人物 JSON 模板';head.append(link);const reset=document.querySelector('#resetPrompt');if(reset&&c?.view==='multi')reset.onclick=()=>{c.multiPrompt=CharacterSheet.spec.prompt;save();render()};};render();
